Database.Load:
	  var pKey = "";
      var additionalCond = "";

	  if(Utils.isDefined(jsonQuery.pKey)){
        pKey =  Utils.convertForDBParam(jsonQuery.pKey, "DomPKey");
        additionalCond += "AND AsignacionCuenta__c.Id = #pKey# ";
	  }

      var sqlParams = {pKey};

      var sqlStmt = "SELECT ";
      sqlStmt +=           "AsignacionCuenta__c.Id AS pKey, ";
      sqlStmt +=           "AsignacionCuenta__c.Id AS portfolioPKey, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Cartera__c AS name, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_NombreZonaDeVenta__c as salesZone, ";
      sqlStmt +=           "AsignacionCuenta__c.AccountId__c AS accountpKey, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Institucion__c AS institutionpKey, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Fecha_de_Asignacion__c AS assignmentDate, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Fecha_Fin_Asignacion__c AS endAssignmentDate, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Ultima_Visita__c AS lastVisitDateSF, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Frecuencia__c AS freq, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Tarea__c AS shift, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Categoria__c AS category, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Tipo_de_zona__c AS zoneType, ";
      sqlStmt +=           "AsignacionCuenta__c.cgf_Cobertura__c AS coverage, ";
      sqlStmt +=           "(SELECT PlannedVisitStartTime FROM Visit WHERE cgf_Cartera__c = #pKey# ORDER BY PlannedVisitStartTime DESC LIMIT 1) lastVisitDateCustom, ";
      sqlStmt +=           "'' AS coverageImage, ";
      sqlStmt +=           "'' AS coverageColor ";
      sqlStmt +=   "FROM   AsignacionCuenta__c ";
	  sqlStmt +=   "WHERE ";
      sqlStmt +=           "AsignacionCuenta__c.IsDeleted = '0' ";
      sqlStmt +=           additionalCond;

      return Utils.replaceMacrosParam(sqlStmt, sqlParams);
